package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.IOException;
import org.junit.jupiter.api.Test;

class TarFileStoreMutaGate1Test {

  @Test
  void getBlockSizeReturns512() throws IOException {
    TarFileStore store = new TarFileStore(null);
    assertEquals(512L, store.getBlockSize());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarFileStoreMutaGate2Test {

  @Test
  void getTotalSpaceReturnsSizeOfTarFile(@TempDir Path dir) throws Exception {
    Path tar = dir.resolve("sample.tar");
    byte[] content = new byte[1024];
    Files.write(tar, content);

    TarFileSystem fs = new TarFileSystem(new TarFileSystemProvider(), tar.toUri(), tar);
    TarFileStore store = new TarFileStore(fs);

    assertEquals(1024L, store.getTotalSpace());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TarFileStoreMutaGate3Test {

  @TempDir
  Path tempDir;

  @Test
  void nameReturnsTarFileName() throws Exception {
    Path tar = tempDir.resolve("sample-archive.tar");
    Files.write(tar, new byte[0]);

    TarFileSystem fileSystem =
        new TarFileSystem(new TarFileSystemProvider(), URI.create("tarball:" + tar.toUri()), tar);
    TarFileStore store = new TarFileStore(fileSystem);

    assertEquals("sample-archive.tar", store.name());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.attribute.BasicFileAttributeView;
import java.nio.file.attribute.FileAttributeView;
import java.nio.file.attribute.PosixFileAttributeView;
import org.junit.jupiter.api.Test;

class TarFileStoreMutaGate4Test {

  @Test
  void supportsFileAttributeViewByClass() {
    TarFileStore store = new TarFileStore(null);

    assertTrue(store.supportsFileAttributeView(BasicFileAttributeView.class));
    assertTrue(store.supportsFileAttributeView(PosixFileAttributeView.class));
    assertFalse(store.supportsFileAttributeView((Class<? extends FileAttributeView>) null));
    assertFalse(store.supportsFileAttributeView(FileAttributeView.class));
  }
}

